    "explanation": "1. CONCEPT & PRINCIPLE:\nAnomalous behavior of the second-period element nitrogen in Group 15.\n\n2. GIVEN INFORMATION / DATA:\nSecond period nitrogen ($Z=7$: $1s^2 2s^2 2p^3$).\n\n3. FORMULA / EQUATION:\nValence shell $n=2$ possesses only one $2s$ and three $2p$ orbitals (total 4 orbitals); $2d$ orbitals do not exist.\n\n4. STEP-BY-STEP REASONING & CALCULATION:\n1. Nitrogen belongs to period 2, where the principal quantum number $n = 2$.\n2. The available valence orbitals are only $2s, 2p_x, 2p_y, 2p_z$ (a maximum of 4 atomic orbitals).\n3. Since nitrogen lacks vacant $d$-orbitals, it cannot expand its octet beyond 8 electrons, limiting its maximum covalency to 4 (as in $NH_4^+$).\n4. In contrast, phosphorus ($n = 3$) has accessible vacant $3d$ orbitals, permitting $sp^3d$ hybridization and pentacovalency ($PCl_5$).\n\n5. FINAL CONCLUSION:\nAbsence of vacant $d$-orbitals in the valence shell of nitrogen.\n\n6. OPTION ANALYSIS & COMMON TRAPS:\nSmall radius and high electronegativity are true characteristics of N, but the specific inability to exceed 4 bonds is strictly due to absence of $d$-orbitals.",
