      "given": "Hydrides: $H_2O$ (373 K), $H_2S$ (213 K), $H_2Se$ (232 K), $H_2Te$ (269 K).",
      "formula": "Boiling point $\\propto$ Molecular weight (van der Waals dispersion forces), with anomalous elevation due to strong H-bonding.",
      "stepByStep": "1. Water ($H_2O$) has an abnormally high boiling point ($373\\text{ K}$) due to extensive intermolecular hydrogen bonding between highly electronegative oxygen and hydrogen.\n2. From $H_2S$ to $H_2Te$, hydrogen bonding is negligible; molecular mass and polarizability increase, which strengthens London dispersion forces.\n3. Consequently, boiling point increases steadily from $H_2S < H_2Se < H_2Te$.\n4. Combining both effects yields the overall sequence: $H_2O > H_2Te > H_2Se > H_2S$.",
      "finalAnswer": "$\\text{H}_2\\text{O} > \\text{H}_2\\text{Te} > \\text{H}_2\\text{Se} > \\text{H}_2\\text{S}$",
      "whyOtherOptionsWrong": "Option B assumes smooth decrease down group; C and D disregard the dominant intermolecular hydrogen bonding in water."
