      "given": "Second period nitrogen ($Z=7$: $1s^2 2s^2 2p^3$).",
      "formula": "Valence shell $n=2$ possesses only one $2s$ and three $2p$ orbitals (total 4 orbitals); $2d$ orbitals do not exist.",
