      "given": "$XeF_4$: Xenon has 8 valence electrons, 4 monovalent fluorine atoms.",
      "formula": "\\text{Steric Number } H = \\frac{1}{2}(V + M - C + A) = \\frac{1}{2}(8 + 4 - 0 + 0) = 6",
      "stepByStep": "1. Xenon has 8 valence electrons. Four electrons form single covalent bonds with 4 F atoms, leaving 4 non-bonding electrons (2 lone pairs).\n2. Steric number = 4 bond pairs + 2 lone pairs = 6, corresponding to $sp^3d^2$ hybridization with octahedral electron-pair arrangement.\n3. To minimize lone pair-lone pair electrostatic repulsions, the two lone pairs occupy trans-axial positions at $180^\\circ$ to each other.\n4. The four fluorine atoms lie in a single plane, resulting in a square planar molecular geometry (with zero net dipole moment).",
      "finalAnswer": "Square planar, $sp^3d^2$",
