    "questionNumber": 58,
    "question": "Q58. The bleaching action of chlorine gas in the presence of moisture is permanent and operates by:",
    "options": {
      "A": "Reduction (nascent hydrogen released)",
      "B": "Oxidation (nascent oxygen released)",
      "C": "Dehydration of colored organic matter",
      "D": "Chlorination forming addition products"
    },
    "optionsList": [
      "Reduction (nascent hydrogen released)",
      "Oxidation (nascent oxygen released)",
      "Dehydration of colored organic matter",
      "Chlorination forming addition products"
    ],
    "correctAnswer": "B",
    "correctIndex": 1,
    "explanation": "1. CONCEPT & PRINCIPLE:\nMechanism of bleaching action of moist chlorine.\n\n2. GIVEN INFORMATION / DATA:\nChlorine reacting with water: $Cl_2 + H_2O \\rightarrow HCl + HOCl \\rightarrow 2HCl + [O]$.\n\n3. FORMULA / EQUATION:\n$\\text{Colored substance} + [O] \\rightarrow \\text{Colorless oxidized product}$\n\n4. STEP-BY-STEP REASONING & CALCULATION:\n1. Dry chlorine gas does not act as a bleaching agent.\n2. In the presence of water, chlorine forms hypochlorous acid: $Cl_2 + H_2O \\rightarrow HCl + HOCl$.\n3. Hypochlorous acid ($HOCl$) is unstable and decomposes readily: $HOCl \\rightarrow HCl + [O]$ (nascent oxygen).\n4. Nascent oxygen oxidizes colored vegetable and organic dyes into permanent colorless compounds.\n5. Because the dye is chemically oxidized, exposure to atmospheric oxygen does not restore color (unlike $SO_2$, which bleaches temporarily by reduction).\n\n5. FINAL CONCLUSION:\nOxidation (nascent oxygen released)\n\n6. OPTION ANALYSIS & COMMON TRAPS:\n$SO_2$ bleaches temporarily by reduction; chlorine bleaches permanently by oxidation.",
    "solutionStructured": {
      "concept": "Mechanism of bleaching action of moist chlorine.",
      "given": "Chlorine reacting with water: $Cl_2 + H_2O \\rightarrow HCl + HOCl \\rightarrow 2HCl + [O]$.",
      "formula": "$\\text{Colored substance} + [O] \\rightarrow \\text{Colorless oxidized product}$",
      "stepByStep": "1. Dry chlorine gas does not act as a bleaching agent.\n2. In the presence of water, chlorine forms hypochlorous acid: $Cl_2 + H_2O \\rightarrow HCl + HOCl$.\n3. Hypochlorous acid ($HOCl$) is unstable and decomposes readily: $HOCl \\rightarrow HCl + [O]$ (nascent oxygen).\n4. Nascent oxygen oxidizes colored vegetable and organic dyes into permanent colorless compounds.\n5. Because the dye is chemically oxidized, exposure to atmospheric oxygen does not restore color (unlike $SO_2$, which bleaches temporarily by reduction).",
      "finalAnswer": "Oxidation (nascent oxygen released)",
      "whyOtherOptionsWrong": "$SO_2$ bleaches temporarily by reduction; chlorine bleaches permanently by oxidation."
    },
