      "C": "$\\text{H}_2\\text{Te} > \\text{H}_2\\text{Se} > \\text{H}_2\\text{S} > \\text{H}_2\\text{O}$",
      "D": "$\\text{H}_2\\text{S} > \\text{H}_2\\text{Se} > \\text{H}_2\\text{Te} > \\text{H}_2\\text{O}$"
