    "question": "Q95. According to VSEPR theory, the molecular geometry and hybridization of the central atom in Xenon tetrafluoride ($\\text{XeF}_4$) are respectively:",
    "options": {
      "A": "Tetrahedral, $sp^3$",
      "B": "See-saw, $sp^3d$",
      "C": "Square planar, $sp^3d^2$",
      "D": "Octahedral, $sp^3d^2$"
    },
    "optionsList": [
      "Tetrahedral, $sp^3$",
      "See-saw, $sp^3d$",
      "Square planar, $sp^3d^2$",
      "Octahedral, $sp^3d^2$"
    ],
    "correctAnswer": "C",
    "correctIndex": 2,
    "explanation": "1. CONCEPT & PRINCIPLE:\nVSEPR prediction of geometry and lone pairs in noble gas compounds.\n\n2. GIVEN INFORMATION / DATA:\n$XeF_4$: Xenon has 8 valence electrons, 4 monovalent fluorine atoms.\n\n3. FORMULA / EQUATION:\n\\text{Steric Number } H = \\frac{1}{2}(V + M - C + A) = \\frac{1}{2}(8 + 4 - 0 + 0) = 6\n\n4. STEP-BY-STEP REASONING & CALCULATION:\n1. Xenon has 8 valence electrons. Four electrons form single covalent bonds with 4 F atoms, leaving 4 non-bonding electrons (2 lone pairs).\n2. Steric number = 4 bond pairs + 2 lone pairs = 6, corresponding to $sp^3d^2$ hybridization with octahedral electron-pair arrangement.\n3. To minimize lone pair-lone pair electrostatic repulsions, the two lone pairs occupy trans-axial positions at $180^\\circ$ to each other.\n4. The four fluorine atoms lie in a single plane, resulting in a square planar molecular geometry (with zero net dipole moment).\n\n5. FINAL CONCLUSION:\nSquare planar, $sp^3d^2$\n\n6. OPTION ANALYSIS & COMMON TRAPS:\nTetrahedral requires 4 bond pairs and 0 lone pairs; See-saw has 4 bond pairs and 1 lone pair ($SF_4$).",
    "solutionStructured": {
      "concept": "VSEPR prediction of geometry and lone pairs in noble gas compounds.",
      "given": "$XeF_4$: Xenon has 8 valence electrons, 4 monovalent fluorine atoms.",
      "formula": "\\text{Steric Number } H = \\frac{1}{2}(V + M - C + A) = \\frac{1}{2}(8 + 4 - 0 + 0) = 6",
      "stepByStep": "1. Xenon has 8 valence electrons. Four electrons form single covalent bonds with 4 F atoms, leaving 4 non-bonding electrons (2 lone pairs).\n2. Steric number = 4 bond pairs + 2 lone pairs = 6, corresponding to $sp^3d^2$ hybridization with octahedral electron-pair arrangement.\n3. To minimize lone pair-lone pair electrostatic repulsions, the two lone pairs occupy trans-axial positions at $180^\\circ$ to each other.\n4. The four fluorine atoms lie in a single plane, resulting in a square planar molecular geometry (with zero net dipole moment).",
      "finalAnswer": "Square planar, $sp^3d^2$",
      "whyOtherOptionsWrong": "Tetrahedral requires 4 bond pairs and 0 lone pairs; See-saw has 4 bond pairs and 1 lone pair ($SF_4$)."
    },
