      "given": "Noble gases trapped in cavities of host crystal lattices (e.g., quinol or ice).",
      "formula": "Clathrate stability requires gas atom diameter to match host cage cavity dimensions (approx $0.4\\text{ nm}$).",
      "stepByStep": "1. Clathrates are cage inclusion compounds where noble gas atoms are trapped mechanically inside cavities of hydrogen-bonded host lattices like beta-quinol or water ice without forming chemical bonds.\n2. Helium (radius $0.93\\text{ \\AA}$) and Neon (radius $1.12\\text{ \\AA}$) are so small that they easily escape through the open interstitial cages of the host lattices.\n3. Larger noble gases (Ar, Kr, Xe) fit snugly into the crystal voids and form stable clathrates.\n4. Therefore, He and Ne do not form clathrates.",
